//! A monetary value backed by an exact `BigDecimal`.
//!
//! The mechanical newtype surface (conversions, parsing, arithmetic bridges,
//! serde/sqlx wrapping, primitives) is generated by [`decimal_newtype!`];
//! only the `Money`-specific semantics — the deliberate bridge to `Amount`
//! quantities — live here.

use crate::entities::types::amount::Amount;

use super::decimal::decimal_newtype;

decimal_newtype!(
    /// A monetary value backed by an exact BigDecimal.
    Money,
    self_ops {
        // NOTE: `Money * Money` and `Money / Money` are deliberately NOT
        // implemented — multiplying or dividing two scaled monetary
        // quantities is meaningless and silently produces wrong units.
        // Scale via the `BigDecimal`/`i64` bridges or the `Amount` bridge
        // below instead.
        Add::add,
        Sub::sub,
    }
);

/// Unit price (€/kg) per purchased quantity (kg) — the inverse of the
/// scaling bridge below. Returns `None` for a zero divisor instead of
/// panicking inside BigDecimal (weights can be user-influenced).
impl Money {
    pub fn checked_div_amount(&self, rhs: &Amount) -> Option<Money> {
        if rhs.is_zero() {
            return None;
        }
        Some(Money(self.0.clone() / rhs.get().clone()))
    }
}

/// Scaling a unit price (€/kg) by a physical quantity (kg) yields money.
/// This is the one deliberate bridge between the two types.
impl std::ops::Mul<&Amount> for Money {
    type Output = Money;
    fn mul(self, rhs: &Amount) -> Money {
        Money(self.0 * rhs.get().clone())
    }
}

impl std::ops::Mul<&Amount> for &Money {
    type Output = Money;
    fn mul(self, rhs: &Amount) -> Money {
        Money(self.0.clone() * rhs.get().clone())
    }
}
